const crypto = require('crypto');
const item = $input.first();
const headers = item.json.headers || {};
function ignored(reason) { return [{ json: { status: 'ignored', reason } }]; }
const secret = $env.ZALO_PERSONAL_EVENT_SECRET;
if (!secret || !item.binary?.data) return ignored('event secret or raw body missing');
let raw;
try { raw = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch (_) { return ignored('raw body unavailable'); }
if (!Buffer.isBuffer(raw) || !raw.length) return ignored('raw body unavailable');
const ts = String(headers['x-adapter-timestamp'] || '');
const signature = String(headers['x-adapter-signature'] || '');
if (!/^\d{10}$/.test(ts) || Math.abs(Date.now() / 1000 - Number(ts)) > 300 || !/^sha256=[a-f0-9]{64}$/.test(signature)) return ignored('invalid adapter event signature');
const expected = crypto.createHmac('sha256', secret).update(ts + '.').update(raw).digest();
if (!crypto.timingSafeEqual(expected, Buffer.from(signature.slice(7), 'hex'))) return ignored('invalid adapter event signature');
let body;
try { body = JSON.parse(raw.toString('utf8')); } catch (_) { return ignored('invalid event JSON'); }
if (!body || typeof body !== 'object' || Array.isArray(body) || typeof body.eventId !== 'string' || !body.eventId || typeof body.sourceMessageId !== 'string' || !body.sourceMessageId || body.isSelf !== false || ![0, 'USER', 'user'].includes(body.threadType) || typeof body.threadId !== 'string' || !body.threadId || typeof body.text !== 'string' || !body.text.trim()) return ignored('invalid private message event');
if (!$env.N8N_DATA_API_SECRET || !$env.N8N_DATA_API_TENANT || !$env.ZALO_PERSONAL_COMMAND_SECRET) return ignored('integration secrets are not configured');
const state = $getWorkflowStaticData('global');
state.seen = state.seen || {};
state.cooldown = state.cooldown || {};
const key = body.eventId + ':' + body.sourceMessageId;
if (state.seen[key]) return [{ json: { status: 'duplicate', eventId: body.eventId } }];
state.seen[key] = Date.now();
const dataTimestamp = String(Math.floor(Date.now() / 1000));
const dataSignature = 'sha256=' + crypto.createHmac('sha256', $env.N8N_DATA_API_SECRET).update(dataTimestamp + '.' + $env.N8N_DATA_API_TENANT).digest('hex');
return [{ json: { status: 'valid', event: body, dataTimestamp, dataSignature } }];

const config = $input.first().json;
const body = $('Validate Event').first().json.event;
function ignored(reason) { return [{ json: { status: 'ignored', reason } }]; }
if (config.enabled !== true) return ignored('auto reply is disabled');
function folded(value) { return value.normalize('NFD').replace(/\p{M}/gu, '').replace(/[đĐ]/g, 'd').toLowerCase().replace(/\s+/g, ' ').trim(); }
function matches(text, trigger) {
  if (typeof trigger !== 'string' || !trigger.trim()) return false;
  return folded(text).includes(folded(trigger));
}
const candidates = [];
if (config.phone?.enabled === true && Array.isArray(config.phone.triggers) && config.phone.triggers.some(t => matches(body.text, t))) {
  candidates.push({ type: 'phone', ruleId: 'phone', text: config.phone.text });
}
if (config.qr?.enabled === true && Array.isArray(config.qr.triggers) && config.qr.triggers.some(t => matches(body.text, t))) {
  candidates.push({ type: 'qr', ruleId: 'qr', image: config.qr.image, caption: config.qr.caption || '' });
}
if (Array.isArray(config.custom)) {
  for (const c of config.custom) {
    if (c.enabled === true && Array.isArray(c.triggers) && c.triggers.some(t => matches(body.text, t))) {
      candidates.push({ type: 'custom', ruleId: c.id, text: c.text });
    }
  }
}
if (candidates.length !== 1) return ignored(candidates.length ? 'ambiguous rules' : 'no matching rule');
const match = candidates[0];
if ((match.type === 'phone' || match.type === 'custom') && (typeof match.text !== 'string' || !match.text.trim() || match.text.length > 4000)) {
  return ignored(match.type + ' text is not configured');
}
if (match.type === 'qr' && (!match.image || !/^[A-Za-z0-9_-]{1,120}\.(?:png|jpg|jpeg)$/.test(match.image.filename || '') || !['image/png', 'image/jpeg'].includes(match.image.mime))) {
  return ignored('QR image is not configured');
}
const seconds = Number($env.ZALO_PERSONAL_COOLDOWN_SECONDS || 300);
if (!Number.isFinite(seconds) || seconds < 0) return ignored('invalid cooldown configuration');
const state = $getWorkflowStaticData('global');
const cooldownKey = body.threadId + ':' + match.ruleId;
if (state.cooldown?.[cooldownKey] && Date.now() - state.cooldown[cooldownKey] < seconds * 1000) return ignored('cooldown');
return [{
  json: {
    status: 'ready',
    rule: match.ruleId,
    ruleType: match.type,
    cooldownKey,
    eventId: body.eventId,
    threadId: body.threadId,
    text: (match.type === 'phone' || match.type === 'custom') ? match.text : '',
    image: match.type === 'qr' ? match.image : null,
    caption: match.type === 'qr' ? match.caption : ''
  }
}];

const crypto = require('crypto');
const ready = $('Evaluate Config').first().json;
function ignored(reason) { return [{ json: { status: 'ignored', reason } }]; }
const secret = $env.ZALO_PERSONAL_COMMAND_SECRET;
if (!secret || ready.status !== 'ready') return ignored('command unavailable');
const isText = ready.ruleType === 'phone' || ready.ruleType === 'custom';
const command = {
  eventId: ready.eventId + ':' + ready.rule,
  action: isText ? 'send_text' : 'send_image',
  threadId: ready.threadId,
  threadType: 0
};
if (isText) {
  command.text = ready.text;
} else {
  if (!$input.first().binary?.data) return ignored('QR image unavailable');
  let image;
  try { image = await this.helpers.getBinaryDataBuffer(0, 'data'); } catch (_) { return ignored('QR image unavailable'); }
  if (!Buffer.isBuffer(image) || !image.length || image.length > 5 * 1024 * 1024) return ignored('invalid QR image');
  command.filename = ready.image.filename;
  command.mime = ready.image.mime;
  command.data = image.toString('base64');
  command.caption = ready.caption;
}
const commandRaw = JSON.stringify(command);
const commandTimestamp = String(Math.floor(Date.now() / 1000));
const commandSignature = 'sha256=' + crypto.createHmac('sha256', secret).update(commandTimestamp + '.' + commandRaw).digest('hex');
return [{ json: { status: 'prepared', rule: ready.rule, eventId: ready.eventId, cooldownKey: ready.cooldownKey, commandRaw, commandTimestamp, commandSignature } }];

const result = $input.first().json;
const prepared = $('Prepare Command').first().json;
if (result.status !== 'sent' || result.eventId !== prepared.eventId + ':' + prepared.rule) return [{ json: { status: 'ignored', reason: 'adapter did not confirm send' } }];
const state = $getWorkflowStaticData('global');
state.cooldown = state.cooldown || {};
state.cooldown[prepared.cooldownKey] = Date.now();
return [{ json: { status: 'sent', eventId: prepared.eventId, rule: prepared.rule } }];
